<!-- SECTION 7: 7-STEP PROCESS -->
<section class="steps-section" id="procedure-section">
    <div class="section-container">
        <header class="section-header" style="text-align:center;margin-bottom:48px;">
            <span class="section-eyebrow">Our Process</span>
            <h2 class="section-title">How to Respond to an Income Tax Demand Notice u/s 156</h2>
            <p class="section-subtitle" style="text-align:left;max-width:100%;">Follow these steps on the income tax e-filing portal (incometaxindia.gov.in) to submit your response within 30 days of service [Section 220(1)].</p>
        </header>
        <div class="steps-container">
            <div class="step-card"><div class="step-content"><span class="step-badge">Step 1</span><h3 class="step-title">Log in to the e-Filing Portal</h3><p class="step-description">Visit incometaxindia.gov.in. Enter your PAN, password, and captcha to access your account.</p><div class="step-highlights"><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Portal accessed</span><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Account logged in</span></div></div><div class="step-visual"><div class="step-illustration"><div class="illustration-icon"><svg viewBox="0 0 120 100" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="20" y="10" width="80" height="60" rx="6" fill="#F0F4F8" stroke="#14365F" stroke-width="1.5"/><rect x="30" y="20" width="60" height="10" rx="3" fill="#FFF3E0" stroke="#F5A623" stroke-width="1"/><text x="60" y="28" font-size="6" fill="#14365F" font-weight="600" text-anchor="middle" font-family="Arial,sans-serif">PAN LOGIN</text><line x1="30" y1="38" x2="90" y2="38" stroke="#14365F" stroke-width="1.5" opacity="0.3"/><line x1="30" y1="48" x2="85" y2="48" stroke="#14365F" stroke-width="1.5" opacity="0.2"/></svg></div><span class="illustration-label">Logged In</span><span class="step-number-large">01</span></div></div></div>
            <div class="step-card"><div class="step-content"><span class="step-badge">Step 2</span><h3 class="step-title">Navigate to Pending Actions</h3><p class="step-description">Click on 'Pending Actions' from the dashboard menu. Select 'Response to Outstanding Tax Demand'.</p><div class="step-highlights"><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Pending Actions opened</span><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Demand section visible</span></div></div><div class="step-visual"><div class="step-illustration"><div class="illustration-icon"><svg viewBox="0 0 120 100" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="15" y="10" width="90" height="60" rx="6" fill="#F0F4F8" stroke="#14365F" stroke-width="1.5"/><rect x="25" y="20" width="70" height="10" rx="3" fill="#14365F"/><text x="60" y="28" font-size="5" fill="#fff" font-weight="600" text-anchor="middle" font-family="Arial,sans-serif">PENDING ACTIONS</text><rect x="25" y="38" width="70" height="10" rx="3" fill="#FFF3E0" stroke="#F5A623" stroke-width="1"/><text x="60" y="46" font-size="5" fill="#E8712C" font-weight="600" text-anchor="middle" font-family="Arial,sans-serif">OUTSTANDING DEMAND</text></svg></div><span class="illustration-label">Navigated</span><span class="step-number-large">02</span></div></div></div>
            <div class="step-card"><div class="step-content"><span class="step-badge">Step 3</span><h3 class="step-title">View the Demand Notice</h3><p class="step-description">The notice details appear - assessment year, demand amount, section under which raised, and due date. Download the PDF notice for your records.</p><div class="step-highlights"><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Demand details reviewed</span><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> PDF downloaded</span></div></div><div class="step-visual"><div class="step-illustration"><div class="illustration-icon"><svg viewBox="0 0 120 100" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="20" y="10" width="80" height="60" rx="6" fill="#F0F4F8" stroke="#14365F" stroke-width="1.5"/><rect x="30" y="20" width="25" height="6" rx="2" fill="#E8712C"/><text x="42" y="24" font-size="5" fill="#fff" font-weight="600" text-anchor="middle" font-family="Arial,sans-serif">S.156</text><line x1="30" y1="34" x2="90" y2="34" stroke="#14365F" stroke-width="1.5" opacity="0.3"/><text x="60" y="46" font-size="8" fill="#E8712C" font-weight="700" text-anchor="middle" font-family="Arial,sans-serif">INR X,XX,XXX</text><line x1="30" y1="54" x2="85" y2="54" stroke="#14365F" stroke-width="1.5" opacity="0.2"/></svg></div><span class="illustration-label">Notice Viewed</span><span class="step-number-large">03</span></div></div></div>
            <div class="step-card"><div class="step-content"><span class="step-badge">Step 4</span><h3 class="step-title">Verify the Demand Against Your Records</h3><p class="step-description">Compare the demand with your ITR, Form 26AS, AIS, and the assessment order. Check for arithmetical errors, TDS credit mismatches, or incorrect additions.</p><div class="step-highlights"><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Computation verified</span><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Errors identified</span></div></div><div class="step-visual"><div class="step-illustration"><div class="illustration-icon"><svg viewBox="0 0 120 100" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="10" y="10" width="100" height="60" rx="6" fill="#F0F4F8" stroke="#14365F" stroke-width="1.5"/><line x1="60" y1="10" x2="60" y2="70" stroke="#14365F" stroke-width="1" opacity="0.3"/><text x="35" y="28" font-size="6" fill="#14365F" font-weight="600" text-anchor="middle" font-family="Arial,sans-serif">DEMAND</text><text x="85" y="28" font-size="6" fill="#10B981" font-weight="600" text-anchor="middle" font-family="Arial,sans-serif">ITR + 26AS</text><rect x="20" y="42" width="80" height="14" rx="3" fill="#E8F5E9" stroke="#10B981" stroke-width="1"/><text x="60" y="52" font-size="6" fill="#14365F" font-weight="700" text-anchor="middle" font-family="Arial,sans-serif">COMPARE</text></svg></div><span class="illustration-label">Verified</span><span class="step-number-large">04</span></div></div></div>
            <div class="step-card"><div class="step-content"><span class="step-badge">Step 5</span><h3 class="step-title">Select Your Response Option</h3><p class="step-description">Three options: (a) Demand is Correct - if you agree; (b) Demand is Partially Incorrect; (c) Demand is Incorrect - if you fully dispute.</p><div class="step-highlights"><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Option selected</span><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Reason documented</span></div></div><div class="step-visual"><div class="step-illustration"><div class="illustration-icon"><svg viewBox="0 0 120 100" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="10" y="5" width="100" height="70" rx="6" fill="#F0F4F8" stroke="#14365F" stroke-width="1.5"/><rect x="20" y="15" width="80" height="14" rx="3" fill="#E8F5E9" stroke="#10B981" stroke-width="1"/><text x="60" y="25" font-size="5" fill="#14365F" font-weight="600" text-anchor="middle" font-family="Arial,sans-serif">CORRECT</text><rect x="20" y="33" width="80" height="14" rx="3" fill="#FFF3E0" stroke="#F5A623" stroke-width="1"/><text x="60" y="43" font-size="5" fill="#14365F" font-weight="600" text-anchor="middle" font-family="Arial,sans-serif">PARTIALLY INCORRECT</text><rect x="20" y="51" width="80" height="14" rx="3" fill="#FDE8E8" stroke="#E8712C" stroke-width="1"/><text x="60" y="61" font-size="5" fill="#14365F" font-weight="600" text-anchor="middle" font-family="Arial,sans-serif">INCORRECT</text></svg></div><span class="illustration-label">Option Chosen</span><span class="step-number-large">05</span></div></div></div>
            <div class="step-card"><div class="step-content"><span class="step-badge">Step 6</span><h3 class="step-title">Pay or Dispute the Demand</h3><p class="step-description">If agreeing: pay via Challan 280 on e-Pay Tax portal. If disputing: select disagreement reason from dropdown and upload supporting documents.</p><div class="step-highlights"><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Payment made OR</span><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Dispute filed with evidence</span></div></div><div class="step-visual"><div class="step-illustration"><div class="illustration-icon"><svg viewBox="0 0 120 100" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="10" y="10" width="100" height="60" rx="6" fill="#F0F4F8" stroke="#14365F" stroke-width="1.5"/><rect x="15" y="25" width="40" height="30" rx="4" fill="#E8F5E9" stroke="#10B981" stroke-width="1.2"/><text x="35" y="43" font-size="6" fill="#14365F" font-weight="700" text-anchor="middle" font-family="Arial,sans-serif">PAY</text><rect x="65" y="25" width="40" height="30" rx="4" fill="#FFF3E0" stroke="#F5A623" stroke-width="1.2"/><text x="85" y="43" font-size="6" fill="#E8712C" font-weight="700" text-anchor="middle" font-family="Arial,sans-serif">DISPUTE</text><text x="55" y="20" font-size="7" fill="#14365F" font-weight="700" text-anchor="middle" font-family="Arial,sans-serif">CHOOSE</text></svg></div><span class="illustration-label">Acted</span><span class="step-number-large">06</span></div></div></div>
            <div class="step-card"><div class="step-content"><span class="step-badge">Step 7</span><h3 class="step-title">Apply for Stay if Filing Appeal</h3><p class="step-description">If filing CIT(A) appeal, simultaneously apply to AO for stay of demand before 30 days expire. Attach appeal filing proof. Pay undisputed portion or 20% of demand.</p><div class="step-highlights"><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Stay petition filed</span><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Appeal proof attached</span></div></div><div class="step-visual"><div class="step-illustration"><div class="illustration-icon"><svg viewBox="0 0 120 100" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="15" y="10" width="90" height="65" rx="6" fill="#F0F4F8" stroke="#14365F" stroke-width="1.5"/><text x="60" y="28" font-size="7" fill="#14365F" font-weight="700" text-anchor="middle" font-family="Arial,sans-serif">STAY OF DEMAND</text><line x1="25" y1="34" x2="95" y2="34" stroke="#14365F" stroke-width="1" opacity="0.3"/><rect x="25" y="42" width="70" height="14" rx="3" fill="#FFF3E0" stroke="#F5A623" stroke-width="1"/><text x="60" y="52" font-size="6" fill="#14365F" font-weight="600" text-anchor="middle" font-family="Arial,sans-serif">Section 220(6)</text><circle cx="60" cy="67" r="4" fill="#E8F5E9" stroke="#10B981" stroke-width="1"/><path d="M58 67l1.5 1.5 3-3" stroke="#10B981" stroke-width="1" stroke-linecap="round"/></svg></div><span class="illustration-label">Stay Filed</span><span class="step-number-large">07</span></div></div></div>
            <div class="step-card"><div class="step-content"><span class="step-badge">Step 8</span><h3 class="step-title">Submit and Note Transaction ID</h3><p class="step-description">Click Submit. Record the Transaction ID for reference. If payment was made, upload challan details (BSR code, CIN, date, amount).</p><div class="step-highlights"><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Response submitted</span><span class="highlight-tag"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Transaction ID recorded</span></div></div><div class="step-visual"><div class="step-illustration"><div class="illustration-icon"><svg viewBox="0 0 120 100" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="20" y="8" width="80" height="60" rx="6" fill="#F0F4F8" stroke="#14365F" stroke-width="1.5"/><rect x="35" y="22" width="50" height="14" rx="3" fill="#14365F"/><text x="60" y="32" font-size="6" fill="#fff" font-weight="700" text-anchor="middle" font-family="Arial,sans-serif">SUBMIT</text><line x1="30" y1="44" x2="90" y2="44" stroke="#14365F" stroke-width="1" opacity="0.3"/><circle cx="60" cy="55" r="6" fill="#E8F5E9" stroke="#10B981" stroke-width="1.5"/><path d="M57 55l2 2 4-4" stroke="#10B981" stroke-width="1.5" stroke-linecap="round"/><circle cx="95" cy="15" r="10" fill="#E8F5E9" stroke="#25D366" stroke-width="1.5"/><path d="M91 15l3 3 5-5" stroke="#25D366" stroke-width="2" stroke-linecap="round"/></svg></div><span class="illustration-label">Complete</span><span class="step-number-large">08</span></div></div></div>
            <div class="highlight-box" style="margin-top:32px;"><p><strong>Important:</strong> If no response is submitted within 30 days, the demand becomes final and may be adjusted against any refund due or initiate recovery action including bank attachment.</p></div>

        </div>
    </div>
</section>

<!-- SECTION 8: DOCUMENTS REQUIRED -->
<section class="content-section" id="documents-section">
    <div class="content-container">
        <div class="text-content">
            <h2 class="section-title">Documents Checklist for Section 156 Response</h2>
            <div class="content-text">
                
                <ul>
                    <li>Copy of the Section 156 demand notice (download from portal)</li>
